export interface ConnectorConfig {
  /** Shopify shared secret for HMAC-SHA256 verification (from SHOPIFY_CLIENT_SECRET).
   *  Note: HMAC verification is expected to be performed by the webhook handler before calling this connector.
   *  This secret is included in config for completeness and potential future use. */
  shopifyClientSecret: string;
  /** Slack bot token with chat:write scope (from SLACK_BOT_TOKEN). */
  slackBotToken: string;
  /** Target Slack channel ID (e.g., C1234567890) or name (e.g., #general). */
  slackChannel: string;
  /** Injected fetch for testing. */
  fetch?: typeof fetch;
}

export interface ShopifyOrderPayload {
  id: number;
  name: string;
  email: string;
  total_price: string;
  currency: string;
}

export interface ConnectorResult {
  slackMessageTs: string;
  slackChannel: string;
}

const REQUIRED_FIELDS: (keyof ShopifyOrderPayload)[] = ['id', 'name', 'email', 'total_price', 'currency'];
const SLACK_API_URL = 'https://slack.com/api/chat.postMessage';

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be a non-null object');
  }
  const obj = payload as Record<string, unknown>;
  for (const field of REQUIRED_FIELDS) {
    if (!(field in obj) || obj[field] === undefined || obj[field] === null) {
      throw new Error(`Missing required field: ${field}`);
    }
    if (field !== 'id' && typeof obj[field] !== 'string') {
      throw new Error(`Field ${field} must be a string`);
    }
    if (field === 'id' && typeof obj[field] !== 'number') {
      throw new Error('Field id must be a number');
    }
  }
}

function formatSlackMessage(payload: ShopifyOrderPayload): string {
  return `New order ${payload.name} from ${payload.email}: $${payload.total_price} ${payload.currency}`;
}

export async function handle(payload: ShopifyOrderPayload, config: ConnectorConfig): Promise<ConnectorResult> {
  validatePayload(payload);

  const fetchImpl = config.fetch ?? fetch;
  const text = formatSlackMessage(payload);

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text,
    }),
  });

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for ${SLACK_API_URL}`);
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string };
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false for ${SLACK_API_URL}`);
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  };
}

