    const { fetch, calls } = fakeFetch((req) => jsonResponse(TARGET_ENDPOINTS[0].response, 200));

    const payload: ShopifyOrderPayload = {
      id: 999,
      name: '#500',
      email: 'buyer@shop.com',
      total_price: '42.50',
      currency: 'EUR',
