    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'channel_not_found' }, 404));

    const payload: ShopifyOrderPayload = {
      id: 123456789,
      name: '#1001',
      email: 'customer@example.com',
      total_price: '129.99',
      currency: 'USD',
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Slack API error: 404 Not Found for https://slack.com/api/chat.postMessage'
    );
    expect(calls).toHaveLength(1);
  });

  it('throws when Slack returns ok=false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'invalid_auth' }, 200));

    const payload: ShopifyOrderPayload = {
      id: 123456789,
      name: '#1001',
      email: 'customer@example.com',
      total_price: '129.99',
      currency: 'USD',
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Slack API returned ok=false for https://slack.com/api/chat.postMessage'
    );
  });

